package com.company.platform.commerce.domain.product;
import java.time.Instant;import java.util.UUID;
public final class Product { private final UUID id,tenantId;private final SKU sku;private ProductName name;private String description;private ProductStatus status;private final Instant createdAt;private Instant updatedAt;
 private Product(UUID id,UUID tenantId,SKU sku,ProductName name,String description,ProductStatus status,Instant createdAt,Instant updatedAt){if(tenantId==null)throw new IllegalArgumentException("tenant required");this.id=id==null?UUID.randomUUID():id;this.tenantId=tenantId;this.sku=sku;this.name=name;this.description=description;this.status=status==null?ProductStatus.DRAFT:status;this.createdAt=createdAt==null?Instant.now():createdAt;this.updatedAt=updatedAt==null?this.createdAt:updatedAt;}
 public static Product create(UUID tenantId,SKU sku,ProductName name,String description){return new Product(null,tenantId,sku,name,description,null,null,null);}public static Product rehydrate(UUID id,UUID tenantId,SKU sku,ProductName name,String description,ProductStatus status,Instant createdAt,Instant updatedAt){return new Product(id,tenantId,sku,name,description,status,createdAt,updatedAt);}
 public void update(ProductName name,String description){this.name=name;this.description=description;this.updatedAt=Instant.now();}public void activate(){if(status==ProductStatus.INACTIVE||status==ProductStatus.DRAFT){status=ProductStatus.ACTIVE;updatedAt=Instant.now();}}public void deactivate(){status=ProductStatus.INACTIVE;updatedAt=Instant.now();}
 public UUID id(){return id;}public UUID tenantId(){return tenantId;}public SKU sku(){return sku;}public ProductName name(){return name;}public String description(){return description;}public ProductStatus status(){return status;}public Instant createdAt(){return createdAt;}public Instant updatedAt(){return updatedAt;}
}
